let status = "green";
let text = "";

const minsUntil = (time) => {
    const msUntilTime = time.getTime() - now.getTime();
    return Math.ceil(msUntilTime / 60000);
};

let now = new Date(msg.timestamp && !isNaN(msg.timestamp) ? msg.timestamp : Date.now());
if (isNaN(now.getTime())) {
    now = new Date();
}
now.setSeconds(0, 0);

const hourMinutesStr = now.toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
});

let nextDepartureTime = null;

let departures = flow.get('departureCache') || [];

// Drop stale (past) departures
while (departures.length > 0) {
    let depTime = new Date(departures[0]);
    if (depTime > now) {
        nextDepartureTime = depTime;
        break; // Found our closest upcoming departure
    } else {
        departures.shift(); // Remove past departure
    }
}

if (!nextDepartureTime) {
    node.status({ fill: "red", shape: "dot", text: "no departure data" });
    msg.payload = {
        "text": hourMinutesStr,
        "textOffset": 5,
        "duration": 7
    };
    msg.iconColor = "";
    return msg;
}

let prognosis = flow.get('prognosisCache') || [];
while (prognosis.length > 0) {
    let progTime = new Date(prognosis[0]);
    if (progTime > nextDepartureTime) {
        break;
    } else {
        prognosis.shift(); // Keep only future prognosis
    }
}

const etaDepartures = [];
for (const progStr of prognosis) {
    let progTime = new Date(progStr);
    etaDepartures.push(minsUntil(progTime));
}

text = `Cached ${departures.length}`;

// Calculate time window variables
const minsUntilDeparture = minsUntil(nextDepartureTime);

let iconColor = "";

if (minsUntilDeparture > 4) {
    iconColor = "green";
} else if (minsUntilDeparture > 2 && minsUntilDeparture <= 4) {
    iconColor = "yellow";
} else if (minsUntilDeparture <= 2) {
    iconColor = "red";
}

const draw = [];
const y = 7;
const startX = 12;
const maxX = 31;

const segments = [
    { len: 2, color: "#FF0000" }, // Final 2 minutes (Red)
    { len: 2, color: "#FFFF00" }, // 2 minutes before that (Yellow)
    { len: 20, color: "#00FF00" } // Everything else (Green)
];

let currentX = startX;
let remainingToDraw = minsUntilDeparture;

for (const seg of segments) {
    if (remainingToDraw <= 0) break;

    let drawLen = Math.min(remainingToDraw, seg.len);
    let endX = currentX + drawLen - 1;
    if (endX > maxX) endX = maxX;
    draw.push({
        "dl": [currentX, y, endX, y, seg.color]
    });

    if (endX >= maxX) break;
    currentX += seg.len;
    remainingToDraw -= seg.len;
}

for (const etaMins of etaDepartures) {
    let progX = startX + etaMins - 1;
    if (progX > maxX) {
        break;
    }
    draw.push({
        "dp": [progX, y, "#0000FF"]
    });
}

msg.payload = {
    "text": hourMinutesStr,
    "textOffset": 5,
    "duration": 113
};

msg.iconColor = iconColor;
msg.progress = draw;
msg.minsUntilDeparture = minsUntilDeparture;
msg.etaDepartures = etaDepartures;

node.status({ fill: status, shape: "dot", text: `${iconColor} ${hourMinutesStr} (${minsUntilDeparture}m, ${etaDepartures[0]}m left) ${text}` });

return msg;

