if (msg.payload && msg.payload.connections) {
    let connections = msg.payload.connections;

    let departureCache = [];
    let prognosisCache = [];
    for (let i = 0; i < Math.min(connections.length, 10); i++) {
        if (!connections[i].from) continue;
        if (connections[i].from.departure) {
            departureCache.push(connections[i].from.departure);
        }
        if (connections[i].from.prognosis.departure) {
            prognosisCache.push(connections[i].from.prognosis.departure);
        }
    }

    flow.set('departureCache', departureCache);
    flow.set('prognosisCache', prognosisCache);
} 

return msg;

const now = new Date();
const currentHour = now.getHours();
const targetHour = 19; // 7 PM

// Determine if we are looking at today or tomorrow
let targetDate = new Date();
if (currentHour >= targetHour) {
    // It's past 7 PM, look at tomorrow
    targetDate.setDate(now.getDate() + 1);
}

const targetDateStr = targetDate.toISOString().split('T')[0];
const times = msg.payload.hourly.time;
const precipValues = msg.payload.hourly.precipitation;

let maxPrecip = 0;
let hoursChecked = 0;

for (let i = 0; i < times.length; i++) {
    const forecastDate = new Date(times[i]);
    const fHour = forecastDate.getHours();
    const fDateStr = forecastDate.toISOString().split('T')[0];

    // Filter: Match the target date and ensure hour is <= 19:00
    if (fDateStr === targetDateStr && fHour <= targetHour) {
        // If it's today, only look from 'now' forward. 
        // If it's tomorrow, look from midnight (0:00) forward.
        const isToday = (targetDateStr === now.toISOString().split('T')[0]);
        if (!isToday || fHour >= currentHour) {
            const amount = precipValues[i];
            if (amount > maxPrecip) {
                maxPrecip = amount;
            }
            hoursChecked++;
        }
    }
}

// Map max mm to 0-10 scale (sqrt scale for sensitivity)
// 10mm = 10, 2.5mm = 5, 0.1mm = 1
let score = 0;
if (maxPrecip > 0) {
    score = Math.min(10, Math.sqrt(maxPrecip / 10) * 10);
}

msg.payload = {
    precipitation_score: parseFloat(score.toFixed(1)),
    max_mm_predicted: maxPrecip,
    target_date: targetDateStr,
    hours_in_window: hoursChecked
};

return msg;

const score = Math.round(msg.payload.precipitation_score || 0);

let drawCommands = [
];

const blue = "#0040FF";

if (score >= 1) drawCommands.push({ "dp": [1, 0, blue] }); // Drop 1
if (score >= 3) drawCommands.push({ "dp": [6, 1, blue] }); // Drop 2
if (score >= 5) {
    drawCommands.push({ "dp": [3, 7, blue] }, { "dp": [4, 7, blue] });
}
if (score >= 7) {
    drawCommands.push({ "dp": [0, 1, blue] }, { "dp": [7, 0, blue] });
    drawCommands.push({ "dp": [2, 7, blue] }, { "dp": [5, 7, blue] });
}
if (score >= 9) {
    drawCommands.push({ "dp": [1, 7, blue] }, { "dp": [6, 7, blue] });
    drawCommands.push({ "dp": [0, 5, blue] }, { "dp": [7, 5, blue] });
}

msg.payload = {
    "weather_icon": drawCommands,
};

return msg;
